-- The two checklists published on 2026-10-08: getting through a family
-- visit (Family) and the week spent waiting on news (Worry).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-08`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('getting-through-a-family-visit', 'Getting Through a Family Visit', 'For the holiday weekend or the trip home where the old patterns are waiting. It helps you decide beforehand what you will and will not get into, build in time away from the room, and leave without a week of regret.', 'Family', '["Decide the two topics you will not discuss — a line chosen in advance is easier to hold.", "Book your own transport there and back — being able to leave changes the whole visit.", "Pick an end time before you arrive — an open-ended visit runs until something goes wrong.", "Have one sentence ready to change the subject — a prepared exit beats a clever answer.", "Take a walk or an errand halfway through — twenty minutes out of the room resets a lot.", "Text one person outside the family during the day — an outside voice keeps the room in proportion.", "Pick one person you are glad to see — aiming the visit at them carries you through the rest.", "Plan something easy for the evening you get back — the landing matters as much as the visit."]'::jsonb, 'as needed', array['Family', 'Boundaries']::text[], 1, '2026-10-08T16:00:00+00:00'::timestamptz),
  ('the-week-you-are-waiting-on-news', 'The Week You Are Waiting on News', 'For the stretch between a test, an application or a decision and the answer, when nothing you do changes the outcome. It helps you put the waiting somewhere, keep the days usable, and stop rehearsing every version of the result.', 'Worry', '["Find out when the answer actually comes — a known date is easier to wait out than an open one.", "Set one time a day to check for it — all-day checking turns one wait into fifty.", "Write the worst outcome and your first three steps — a plan makes the bad version survivable.", "Stop researching once you have what you need — more reading rarely changes the answer.", "Put something in the calendar for each day — an empty week fills up with the waiting.", "Tell one person you are waiting — carrying it silently makes it heavier than it is.", "Move your body once a day, even briefly — waiting sits in the body as much as the head.", "Notice when you are rehearsing and name it — the fiftieth run-through tells you nothing new."]'::jsonb, 'as needed', array['Worry', 'Anxiety']::text[], 1, '2026-10-08T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
